targets.expr:
max by (job,instance) (
  system_uptime_seconds{job=~"$job",instance=~"$instance"}
)
or
max by (job,instance) (
  system_uptime{job=~"$job",instance=~"$instance"}
)

max by (job,instance,host_name) (
  target_info{host_name!="", job=~"$job",instance=~"$instance"}
)

max by (job,instance,os_name) (
  label_replace(target_info{os_description!="", job=~"$job",instance=~"$instance"}, "os_name", "$1", "os_description", "(.+?)( [(].*)?")
)

max by (job,instance) (
  system_cpu_load_average_1m{job=~"$job",instance=~"$instance"}
)

max by (job,instance) (
  system_cpu_logical_count{job=~"$job",instance=~"$instance"}
)

max by (job,instance) (
  system_memory_limit_bytes{job=~"$job",instance=~"$instance"}
)
or
max by (job,instance) (
  system_memory_limit{job=~"$job",instance=~"$instance"}
)

100 * (
  max by (job,instance) (
  system_memory_utilization_ratio{state="used", job=~"$job",instance=~"$instance"}
)
)
or
100 * (
  max by (job,instance) (
  system_memory_utilization{state="used", job=~"$job",instance=~"$instance"}
)
)

sum by (job,instance) (
  system_filesystem_usage_bytes{mountpoint="/", type!="", mountpoint!="", job=~"$job",instance=~"$instance"}
)
or
sum by (job,instance) (
  system_filesystem_usage{mountpoint="/", type!="", mountpoint!="", job=~"$job",instance=~"$instance"}
)

100 * (
  max by (job,instance) (
  system_filesystem_utilization_ratio{mountpoint="/", type!="", mountpoint!="", job=~"$job",instance=~"$instance"}
)
)
or
100 * (
  max by (job,instance) (
  system_filesystem_utilization{mountpoint="/", type!="", mountpoint!="", job=~"$job",instance=~"$instance"}
)
)

count by (job,instance) (
  ALERTS{alertstate="firing", severity="critical", job=~"$job",instance=~"$instance"}
)

count by (job,instance) (
  ALERTS{alertstate="firing", severity="warning", job=~"$job",instance=~"$instance"}
)

topk(25,
  max by (job,instance) (
  system_cpu_load_average_1m{job=~"$job",instance=~"$instance"}
)
)

topk(25,
  100 * (
  max by (job,instance) (
  system_memory_utilization_ratio{state="used", job=~"$job",instance=~"$instance"}
)
)
)
or
topk(25,
  100 * (
  max by (job,instance) (
  system_memory_utilization{state="used", job=~"$job",instance=~"$instance"}
)
)
)

topk(25,
  sum by (job,instance) (
  rate(system_disk_io_bytes_total{device!="", device!~"dm-.*|md.*", job=~"$job",instance=~"$instance"}[$__rate_interval])
)
)
or
topk(25,
  sum by (job,instance) (
  rate(system_disk_io{device!="", device!~"dm-.*|md.*", job=~"$job",instance=~"$instance"}[$__rate_interval])
)
)

topk(25,
  100 * (
  max by (job,instance,mountpoint) (
  system_filesystem_utilization_ratio{mode!="ro", type!="", mountpoint!="", job=~"$job",instance=~"$instance"}
)
)
)
or
topk(25,
  100 * (
  max by (job,instance,mountpoint) (
  system_filesystem_utilization{mode!="ro", type!="", mountpoint!="", job=~"$job",instance=~"$instance"}
)
)
)

topk(25,
  8 * (
  sum by (job,instance) (
  rate(system_network_io_bytes_total{device!="", device!="lo", job=~"$job",instance=~"$instance"}[$__rate_interval])
)
)
)
or
topk(25,
  8 * (
  sum by (job,instance) (
  rate(system_network_io{device!="", device!="lo", job=~"$job",instance=~"$instance"}[$__rate_interval])
)
)
)

topk(25,
  (
  sum by (job,instance) (
  rate(system_network_errors_total{device!="", device!="lo", job=~"$job",instance=~"$instance"}[$__rate_interval])
)
) and (max by (job,instance) (increase(system_network_errors_total{device!="", device!="lo", job=~"$job",instance=~"$instance"}[$__range] @ end())) > 0)
)
or
topk(25,
  (
  sum by (job,instance) (
  rate(system_network_errors{device!="", device!="lo", job=~"$job",instance=~"$instance"}[$__rate_interval])
)
) and (max by (job,instance) (increase(system_network_errors{device!="", device!="lo", job=~"$job",instance=~"$instance"}[$__range] @ end())) > 0)
)

topk(25,
  (
  sum by (job,instance) (
  rate(system_network_dropped_total{device!="", device!="lo", job=~"$job",instance=~"$instance"}[$__rate_interval])
)
) and (max by (job,instance) (increase(system_network_dropped_total{device!="", device!="lo", job=~"$job",instance=~"$instance"}[$__range] @ end())) > 0)
)
or
topk(25,
  (
  sum by (job,instance) (
  rate(system_network_dropped{device!="", device!="lo", job=~"$job",instance=~"$instance"}[$__rate_interval])
)
) and (max by (job,instance) (increase(system_network_dropped{device!="", device!="lo", job=~"$job",instance=~"$instance"}[$__range] @ end())) > 0)
)
